CREATE TABLE IF NOT EXISTS workflowSchedules (id INT AUTO_INCREMENT PRIMARY KEY, workflowId INT NOT NULL, userId INT NOT NULL, cron VARCHAR(120) NOT NULL, timezone VARCHAR(64) NOT NULL DEFAULT 'America/Sao_Paulo', enabled BOOLEAN NOT NULL DEFAULT TRUE, nextRunAt TIMESTAMP NULL, lastRunAt TIMESTAMP NULL, createdAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updatedAt TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX workflowSchedules_user_idx (userId), INDEX workflowSchedules_workflow_idx (workflowId), INDEX workflowSchedules_next_run_idx (nextRunAt));
